			}
			break;
		}
	} else {
		goto err;
	}
	if (txt && !op->txt) {
		op->txt = strdup ("incorrect");
	}
	return op->len;

  err:
	op->len = 1;
	if (txt) {
		op->txt = strdup ("invalid");
	}
	return op->len;
}

