  for (int channel = 0; channel < channel_size; channel++) {
    test::ExpectTensorNear<float>(
        spectrogram_tensor.SubSlice(channel),
        test::AsTensor<float>({0, 1, 2, 1, 0}, TensorShape({1, 5})), 1e-3);
  }
}

