			ret = send_error(connection, 503);
			free(originurl);
			free(originurl_raw);
			free(querystr);
			return ret;
		}

		querystr=construct_querystring(connection, client, originurl, querystr);
		debug(LOG_DEBUG, "Constructed query string [%s]", querystr);
		debug(LOG_DEBUG, "FAS url [%s]", config->fas_url);

