    int *c_fds_to_keep = NULL;
    Py_ssize_t fds_to_keep_len = PyTuple_GET_SIZE(py_fds_to_keep);

    PyInterpreterState *interp = _PyInterpreterState_GET();
    if ((preexec_fn != Py_None) && interp->finalizing) {
        PyErr_SetString(PyExc_RuntimeError,
                        "preexec_fn not supported at interpreter shutdown");
        return NULL;
    }
    if ((preexec_fn != Py_None) && (interp != PyInterpreterState_Main())) {
        PyErr_SetString(PyExc_RuntimeError,
                        "preexec_fn not supported within subinterpreters");
        return NULL;
    }

    if (close_fds && errpipe_write < 3) {  /* precondition */
        PyErr_SetString(PyExc_ValueError, "errpipe_write must be >= 3");
        return NULL;
    }
    if (_sanity_check_python_fd_sequence(py_fds_to_keep)) {
        PyErr_SetString(PyExc_ValueError, "bad value(s) in fds_to_keep");
        return NULL;
    }

    /* We need to call gc.disable() when we'll be calling preexec_fn */
    if (preexec_fn != Py_None) {
        need_to_reenable_gc = PyGC_Disable();
    }

    char *const *exec_array = _PySequence_BytesToCharpArray(executable_list);
    if (!exec_array)
        goto cleanup;

    /* Convert args and env into appropriate arguments for exec() */
    /* These conversions are done in the parent process to avoid allocating
       or freeing memory in the child process. */
    if (process_args != Py_None) {
        Py_ssize_t num_args;
        /* Equivalent to:  */
        /*  tuple(PyUnicode_FSConverter(arg) for arg in process_args)  */
        fast_args = PySequence_Fast(process_args, "argv must be a tuple");
        if (fast_args == NULL)
            goto cleanup;
        num_args = PySequence_Fast_GET_SIZE(fast_args);
        converted_args = PyTuple_New(num_args);
        if (converted_args == NULL)
            goto cleanup;
        for (Py_ssize_t arg_num = 0; arg_num < num_args; ++arg_num) {
            PyObject *borrowed_arg, *converted_arg;
            if (PySequence_Fast_GET_SIZE(fast_args) != num_args) {
                PyErr_SetString(PyExc_RuntimeError, "args changed during iteration");
                goto cleanup;
            }
            borrowed_arg = PySequence_Fast_GET_ITEM(fast_args, arg_num);
            if (PyUnicode_FSConverter(borrowed_arg, &converted_arg) == 0)
                goto cleanup;
            PyTuple_SET_ITEM(converted_args, arg_num, converted_arg);
        }

        argv = _PySequence_BytesToCharpArray(converted_args);
        Py_CLEAR(converted_args);
        Py_CLEAR(fast_args);
        if (!argv)
            goto cleanup;
    }

    if (env_list != Py_None) {
        envp = _PySequence_BytesToCharpArray(env_list);
        if (!envp)
            goto cleanup;
    }

    if (cwd_obj != Py_None) {
        if (PyUnicode_FSConverter(cwd_obj, &cwd_obj2) == 0)
            goto cleanup;
        cwd = PyBytes_AsString(cwd_obj2);
    }

    // Special initial value meaning that subprocess API was called with
    // extra_groups=None leading to _posixsubprocess.fork_exec(gids=None).
    // We use this to differentiate between code desiring a setgroups(0, NULL)
    // call vs no call at all.  The fast vfork() code path could be used when
    // there is no setgroups call.
    Py_ssize_t extra_group_size = -2;

    if (extra_groups_packed != Py_None) {
#ifdef HAVE_SETGROUPS
        if (!PyList_Check(extra_groups_packed)) {
            PyErr_SetString(PyExc_TypeError,
                    "setgroups argument must be a list");
            goto cleanup;
        }
        extra_group_size = PySequence_Size(extra_groups_packed);

        if (extra_group_size < 0)
            goto cleanup;

        if (extra_group_size > MAX_GROUPS) {
            PyErr_SetString(PyExc_ValueError, "too many extra_groups");
            goto cleanup;
        }

        /* Deliberately keep extra_groups == NULL for extra_group_size == 0 */
        if (extra_group_size > 0) {
            extra_groups = PyMem_RawMalloc(extra_group_size * sizeof(gid_t));
            if (extra_groups == NULL) {
                PyErr_SetString(PyExc_MemoryError,
                        "failed to allocate memory for group list");
                goto cleanup;
            }
        }

        for (Py_ssize_t i = 0; i < extra_group_size; i++) {
            PyObject *elem;
            elem = PySequence_GetItem(extra_groups_packed, i);
            if (!elem)
                goto cleanup;
            if (!PyLong_Check(elem)) {
                PyErr_SetString(PyExc_TypeError,
                                "extra_groups must be integers");
                Py_DECREF(elem);
                goto cleanup;
            } else {
                gid_t gid;
                if (!_Py_Gid_Converter(elem, &gid)) {
                    Py_DECREF(elem);
                    PyErr_SetString(PyExc_ValueError, "invalid group id");
                    goto cleanup;
                }
                extra_groups[i] = gid;
            }
            Py_DECREF(elem);
        }

#else /* HAVE_SETGROUPS */
        PyErr_BadInternalCall();
        goto cleanup;
#endif /* HAVE_SETGROUPS */
    }

    gid_t gid = (gid_t)-1;
    if (gid_object != Py_None) {
#ifdef HAVE_SETREGID
        if (!_Py_Gid_Converter(gid_object, &gid))
            goto cleanup;

#else /* HAVE_SETREGID */
        PyErr_BadInternalCall();
        goto cleanup;
#endif /* HAVE_SETREUID */
    }

    uid_t uid = (uid_t)-1;
    if (uid_object != Py_None) {
#ifdef HAVE_SETREUID
        if (!_Py_Uid_Converter(uid_object, &uid))
            goto cleanup;

#else /* HAVE_SETREUID */
        PyErr_BadInternalCall();
        goto cleanup;
#endif /* HAVE_SETREUID */
    }

    c_fds_to_keep = PyMem_Malloc(fds_to_keep_len * sizeof(int));
    if (c_fds_to_keep == NULL) {
        PyErr_SetString(PyExc_MemoryError, "failed to malloc c_fds_to_keep");
        goto cleanup;
    }
    if (convert_fds_to_keep_to_c(py_fds_to_keep, c_fds_to_keep) < 0) {
        goto cleanup;
    }

    /* This must be the last thing done before fork() because we do not
     * want to call PyOS_BeforeFork() if there is any chance of another
     * error leading to the cleanup: code without calling fork(). */
    if (preexec_fn != Py_None) {
        preexec_fn_args_tuple = PyTuple_New(0);
        if (!preexec_fn_args_tuple)
            goto cleanup;
        PyOS_BeforeFork();
        need_after_fork = 1;
    }

    /* NOTE: When old_sigmask is non-NULL, do_fork_exec() may use vfork(). */
    const void *old_sigmask = NULL;
#ifdef VFORK_USABLE
    /* Use vfork() only if it's safe. See the comment above child_exec(). */
    sigset_t old_sigs;
    if (preexec_fn == Py_None && allow_vfork &&
        uid == (uid_t)-1 && gid == (gid_t)-1 && extra_group_size < 0) {
        /* Block all signals to ensure that no signal handlers are run in the
         * child process while it shares memory with us. Note that signals
         * used internally by C libraries won't be blocked by
         * pthread_sigmask(), but signal handlers installed by C libraries
         * normally service only signals originating from *within the process*,
         * so it should be sufficient to consider any library function that
         * might send such a signal to be vfork-unsafe and do not call it in
         * the child.
         */
        sigset_t all_sigs;
        sigfillset(&all_sigs);
        if ((saved_errno = pthread_sigmask(SIG_BLOCK, &all_sigs, &old_sigs))) {
            goto cleanup;
        }
        old_sigmask = &old_sigs;
    }
#endif

    pid = do_fork_exec(exec_array, argv, envp, cwd,
                       p2cread, p2cwrite, c2pread, c2pwrite,
                       errread, errwrite, errpipe_read, errpipe_write,
                       close_fds, restore_signals, call_setsid, pgid_to_set,
                       gid, extra_group_size, extra_groups,
                       uid, child_umask, old_sigmask,
                       c_fds_to_keep, fds_to_keep_len,
                       preexec_fn, preexec_fn_args_tuple);

    /* Parent (original) process */
    if (pid == (pid_t)-1) {
        /* Capture errno for the exception. */
        saved_errno = errno;
    }

#ifdef VFORK_USABLE
    if (old_sigmask) {
        /* vfork() semantics guarantees that the parent is blocked
         * until the child performs _exit() or execve(), so it is safe
         * to unblock signals once we're here.
         * Note that in environments where vfork() is implemented as fork(),
         * such as QEMU user-mode emulation, the parent won't be blocked,
         * but it won't share the address space with the child,
         * so it's still safe to unblock the signals.
         *
         * We don't handle errors here because this call can't fail
         * if valid arguments are given, and because there is no good
         * way for the caller to deal with a failure to restore
         * the thread signal mask. */
        (void) pthread_sigmask(SIG_SETMASK, old_sigmask, NULL);
    }
#endif

    if (need_after_fork)
        PyOS_AfterFork_Parent();

cleanup:
    if (c_fds_to_keep != NULL) {
        PyMem_Free(c_fds_to_keep);
    }

    if (saved_errno != 0) {
        errno = saved_errno;
        /* We can't call this above as PyOS_AfterFork_Parent() calls back
         * into Python code which would see the unreturned error. */
        PyErr_SetFromErrno(PyExc_OSError);
    }

    Py_XDECREF(preexec_fn_args_tuple);
    PyMem_RawFree(extra_groups);
    Py_XDECREF(cwd_obj2);
    if (envp)
        _Py_FreeCharPArray(envp);
    Py_XDECREF(converted_args);
    Py_XDECREF(fast_args);
    if (argv)
        _Py_FreeCharPArray(argv);
    if (exec_array)
        _Py_FreeCharPArray(exec_array);

    if (need_to_reenable_gc) {
        PyGC_Enable();
    }

    return pid == -1 ? NULL : PyLong_FromPid(pid);
}

before:
void RGBFramebufferModel::load(
  Imf::MultiPartInputFile& file, int partId, bool hasAlpha)
{
    QFuture<void> imageLoading = QtConcurrent::run([this,
                                                    &file,
                                                    partId,
                                                    hasAlpha]() {
        try {
            Imf::InputPart part(file, partId);

            Imath::Box2i datW = part.header().dataWindow();
            m_width           = datW.max.x - datW.min.x + 1;
            m_height          = datW.max.y - datW.min.y + 1;

            m_pixelAspectRatio = part.header().pixelAspectRatio();

            m_dataWindow = QRect(datW.min.x, datW.min.y, m_width, m_height);

            Imath::Box2i dispW = part.header().displayWindow();

            int dispW_width  = dispW.max.x - dispW.min.x + 1;
            int dispW_height = dispW.max.y - dispW.min.y + 1;

            m_displayWindow
              = QRect(dispW.min.x, dispW.min.y, dispW_width, dispW_height);

            // Check if there is specific chromaticities tied to the color
            // representation in this part.
            const Imf::ChromaticitiesAttribute* c
              = part.header().findTypedAttribute<Imf::ChromaticitiesAttribute>(
                "chromaticities");

            Imf::Chromaticities chromaticities;

            if (c != nullptr) {
                chromaticities = c->value();
            }

            m_pixelBuffer = new float[4 * m_width * m_height];

            // Check if there is alpha channel
            if (hasAlpha) {
                std::string      aLayer = m_parentLayer + "A";
                Imf::FrameBuffer framebuffer;

                Imf::Slice aSlice = Imf::Slice::Make(
                  Imf::PixelType::FLOAT,
                  &m_pixelBuffer[3],
                  datW,
                  4 * sizeof(float),
                  4 * m_width * sizeof(float));

                framebuffer.insert(aLayer, aSlice);

                part.setFrameBuffer(framebuffer);
                part.readPixels(datW.min.y, datW.max.y);

            } else {
                for (int y = 0; y < m_height; y++) {
                    for (int x = 0; x < m_width; x++) {
                        m_pixelBuffer[4 * (y * m_width + x) + 3] = 1.f;
                    }
                }
            }

            switch (m_layerType) {
                case Layer_RGB: {
                    std::string rLayer = m_parentLayer + "R";
                    std::string gLayer = m_parentLayer + "G";
                    std::string bLayer = m_parentLayer + "B";

                    Imf::FrameBuffer framebuffer;

                    Imf::Slice rSlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[0],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    Imf::Slice gSlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[1],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    Imf::Slice bSlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[2],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    framebuffer.insert(rLayer, rSlice);
                    framebuffer.insert(gLayer, gSlice);
                    framebuffer.insert(bLayer, bSlice);

                    part.setFrameBuffer(framebuffer);
                    part.readPixels(datW.min.y, datW.max.y);

                    // Handle custom chromaticities
                    Imath::M44f RGB_XYZ = Imf::RGBtoXYZ(chromaticities, 1.f);
                    Imath::M44f XYZ_RGB
                      = Imf::XYZtoRGB(Imf::Chromaticities(), 1.f);

                    Imath::M44f conversionMatrix = RGB_XYZ * XYZ_RGB;

                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        for (int x = 0; x < m_width; x++) {
                            const float r
                              = m_pixelBuffer[4 * (y * m_width + x) + 0];
                            const float g
                              = m_pixelBuffer[4 * (y * m_width + x) + 1];
                            const float b
                              = m_pixelBuffer[4 * (y * m_width + x) + 2];

                            Imath::V3f rgb(r, g, b);
                            rgb *= conversionMatrix;

                            m_pixelBuffer[4 * (y * m_width + x) + 0] = rgb.x;
                            m_pixelBuffer[4 * (y * m_width + x) + 1] = rgb.y;
                            m_pixelBuffer[4 * (y * m_width + x) + 2] = rgb.z;
                        }
                    }
                } break;

                case Layer_YC: {
                    std::string yLayer  = m_parentLayer + "Y";
                    std::string ryLayer = m_parentLayer + "RY";
                    std::string byLayer = m_parentLayer + "BY";

                    Imf::FrameBuffer framebuffer;

                    Imf::Rgba* buff1 = new Imf::Rgba[m_width * m_height];
                    Imf::Rgba* buff2 = new Imf::Rgba[m_width * m_height];

                    float* yBuffer  = new float[m_width * m_height];
                    float* ryBuffer = new float[m_width / 2 * m_height / 2];
                    float* byBuffer = new float[m_width / 2 * m_height / 2];

                    Imf::Slice ySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &yBuffer[0],
                      datW,
                      sizeof(float),
                      m_width * sizeof(float));

                    Imf::Slice rySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &ryBuffer[0],
                      datW,
                      sizeof(float),
                      m_width / 2 * sizeof(float),
                      2,
                      2);

                    Imf::Slice bySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &byBuffer[0],
                      datW,
                      sizeof(float),
                      m_width / 2 * sizeof(float),
                      2,
                      2);

                    framebuffer.insert(yLayer, ySlice);
                    framebuffer.insert(ryLayer, rySlice);
                    framebuffer.insert(byLayer, bySlice);

                    part.setFrameBuffer(framebuffer);
                    part.readPixels(datW.min.y, datW.max.y);

                    // Filling missing values for chroma in the image
                    // TODO: now, naive reconstruction.
                    // Use later Imf::RgbaYca::reconstructChromaHoriz and
                    // Imf::RgbaYca::reconstructChromaVert to reconstruct missing
                    // pixels
                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        for (int x = 0; x < m_width; x++) {
                            const float l = yBuffer[y * m_width + x];

                            /*
                            float ry = 0, by = 0;

                            if (y % 2 == 0) {
                                if (x % 2 == 0) {
                                    ry = ryBuffer[y / 2 * m_width / 2 + x / 2];
                                    by = byBuffer[y / 2 * m_width / 2 + x / 2];
                                } else {
                                    ry = .5 * (ryBuffer[y / 2 * m_width / 2 + x / 2] + ryBuffer[y / 2 * m_width / 2 + x / 2 + 1]);
                                    by = .5 * (byBuffer[y / 2 * m_width / 2 + x / 2] + byBuffer[y / 2 * m_width / 2 + x / 2 + 1]);
                                }
                            } else {
                                if (x % 2 == 0) {
                                    ry = .5 * (ryBuffer[y / 2 * m_width / 2 + x / 2] + ryBuffer[(y / 2 + 1) * m_width / 2 + x / 2]);
                                    by = .5 * (byBuffer[y / 2 * m_width / 2 + x / 2] + byBuffer[(y / 2 + 1) * m_width / 2 + x / 2]);
                                } else {
                                    ry = .25 * (ryBuffer[y / 2 * m_width / 2 + x / 2] + ryBuffer[(y / 2 + 1) * m_width / 2 + x / 2] + ryBuffer[y / 2 * m_width / 2 + x / 2 + 1] + ryBuffer[(y / 2 + 1) * m_width / 2 + x / 2 + 1]);
                                    by = .25 * (byBuffer[y / 2 * m_width / 2 + x / 2] + byBuffer[(y / 2 + 1) * m_width / 2 + x / 2] + byBuffer[y / 2 * m_width / 2 + x / 2 + 1] + byBuffer[(y / 2 + 1) * m_width / 2 + x / 2 + 1]);
                                }
                            }
                            */

                            const float ry
                              = ryBuffer[y / 2 * m_width / 2 + x / 2];
                            const float by
                              = byBuffer[y / 2 * m_width / 2 + x / 2];

                            buff1[y * m_width + x].r = ry;
                            buff1[y * m_width + x].g = l;
                            buff1[y * m_width + x].b = by;
                            // Do not forget the alpha values read earlier
                            buff1[y * m_width + x].a
                              = m_pixelBuffer[4 * (y * m_width + x) + 3];
                        }
                    }

                    Imath::V3f yw = Imf::RgbaYca::computeYw(chromaticities);

                    // Proceed to the YCA -> RGBA conversion
                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        Imf::RgbaYca::YCAtoRGBA(
                          yw,
                          m_width,
                          &buff1[y * m_width],
                          &buff1[y * m_width]);
                    }

                    // Fix over saturated pixels
                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        const Imf::Rgba* scanlines[3];

                        if (y == 0) {
                            scanlines[0] = &buff1[(y + 1) * m_width];
                        } else {
                            scanlines[0] = &buff1[(y - 1) * m_width];
                        }

                        scanlines[1] = &buff1[y * m_width];

                        if (y == m_height - 1) {
                            scanlines[2] = &buff1[(y - 1) * m_width];
                        } else {
                            scanlines[2] = &buff1[(y + 1) * m_width];
                        }

                        Imf::RgbaYca::fixSaturation(
                          yw,
                          m_width,
                          scanlines,
                          &buff2[y * m_width]);
                    }

                    // Handle custom chromaticities
                    Imath::M44f RGB_XYZ = Imf::RGBtoXYZ(chromaticities, 1.f);
                    Imath::M44f XYZ_RGB
                      = Imf::XYZtoRGB(Imf::Chromaticities(), 1.f);

                    Imath::M44f conversionMatrix = RGB_XYZ * XYZ_RGB;

                    #pragma omp parallel for
                    for (int y = 0; y < m_height; y++) {
                        for (int x = 0; x < m_width; x++) {
                            Imath::V3f rgb(
                              buff2[y * m_width + x].r,
                              buff2[y * m_width + x].g,
                              buff2[y * m_width + x].b);

                            rgb = rgb * conversionMatrix;

                            m_pixelBuffer[4 * (y * m_width + x) + 0] = rgb.x;
                            m_pixelBuffer[4 * (y * m_width + x) + 1] = rgb.y;
                            m_pixelBuffer[4 * (y * m_width + x) + 2] = rgb.z;
                        }
                    }

                    delete[] yBuffer;
                    delete[] ryBuffer;
                    delete[] byBuffer;
                    delete[] buff1;
                    delete[] buff2;
                }

                break;

                case Layer_Y: {
                    std::string yLayer = m_parentLayer;

                    Imf::FrameBuffer framebuffer;

                    Imf::Slice ySlice = Imf::Slice::Make(
                      Imf::PixelType::FLOAT,
                      &m_pixelBuffer[0],
                      datW,
                      4 * sizeof(float),
                      4 * m_width * sizeof(float));

                    framebuffer.insert(yLayer, ySlice);

                    part.setFrameBuffer(framebuffer);
                    part.readPixels(datW.min.y, datW.max.y);

                    #pragma omp parallel for
                    for (int i = 0; i < m_height * m_width; i++) {
                        m_pixelBuffer[4 * i + 1] = m_pixelBuffer[4 * i + 0];
                        m_pixelBuffer[4 * i + 2] = m_pixelBuffer[4 * i + 0];
                        m_pixelBuffer[4 * i + 3] = 1.f;
                    }
                } break;
            }

            m_image = QImage(m_width, m_height, QImage::Format_RGBA8888);
            m_isImageLoaded = true;

            emit imageLoaded();

            updateImage();
        } catch (std::exception& e) {
            emit loadFailed(e.what());
            return;
        }
    });

    m_imageLoadingWatcher->setFuture(imageLoading);
}

