                int dispW_width  = dispW.max.x - dispW.min.x + 1;
                int dispW_height = dispW.max.y - dispW.min.y + 1;

                m_displayWindow = QRect(
                  dispW.min.x,
                  dispW.min.y,
                  dispW_width / 2,
                  dispW_height / 2);

                m_pixelBuffer = new float[m_width * m_height];

                // Luminance Chroma channels
                graySlice = Imf::Slice::Make(
                  Imf::PixelType::FLOAT,
