			nf->nf_file = open->op_filp;
			open->op_filp = NULL;
			trace_nfsd_file_create(rqstp, access, nf);
		}

		spin_lock(&fp->fi_lock);
		if (!fp->fi_fds[oflag]) {
			fp->fi_fds[oflag] = nf;
