	release_sock(listener_ssk);

	for (msk = head; msk; msk = next) {
		struct sock *sk = (struct sock *)msk;
		bool do_cancel_work;

		sock_hold(sk);
		lock_sock_nested(sk, SINGLE_DEPTH_NESTING);
		next = msk->dl_next;
		msk->first = NULL;
		msk->dl_next = NULL;

