	struct hlist_nulls_head *hlist;
	struct hlist_nulls_node *hnode;
	struct sock *sk;
	int hash;

	hash = raw_hashfunc(net, nexthdr);
	hlist = &raw_v6_hashinfo.ht[hash];
	rcu_read_lock();
	sk_nulls_for_each(sk, hnode, hlist) {
		/* Note: ipv6_hdr(skb) != skb->data */
